package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	nextInt := func() int {
		scanner.Scan()
		val, _ := strconv.Atoi(scanner.Text())
		return val
	}

	n := nextInt()
	m := nextInt()
	a := [101]int{}

	for i := 0; i < m; i++ {
		b := nextInt()
		a[b]++
	}

	for i := m; i >= 1; i-- {
		k := 0
		for j := 1; j < 101; j++ {
			k += a[j] / i
		}
		if k >= n {
			fmt.Println(i)
			return
		}
	}
	fmt.Println(0)
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

type FastScanner struct {
	reader *bufio.Reader
	buf    []byte
	idx    int
	size   int
}

func NewFastScanner(r *bufio.Reader) *FastScanner {
	return &FastScanner{
		reader: r,
		buf:    make([]byte, 8192),
		idx:    0,
		size:   0,
	}
}

func (s *FastScanner) read() byte {
	if s.idx >= s.size {
		s.idx = 0
		n, err := s.reader.Read(s.buf)
		if err != nil || n == 0 {
			return 0
		}
		s.size = n
	}
	b := s.buf[s.idx]
	s.idx++
	return b
}

func (s *FastScanner) NextInt() int {
	c := s.read()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == 0 {
		c = s.read()
	}
	sign := 1
	if c == '-' {
		sign = -1
		c = s.read()
	}
	res := 0
	for c >= '0' && c <= '9' {
		res = res*10 + int(c-'0')
		c = s.read()
	}
	return res * sign
}

